    { id: 'accuracy', key: 'metaAprovacao', label: 'Meta de acerto', description: 'Taxa de acerto observada' }
  ];
  const items = definitions.map(i => {
    const target = goals[i.key] == null ? null : Math.max(0, number(goals[i.key]));
